@page "/"
@using RecipeShare.Services

<PageTitle>RecipeShare - Home</PageTitle>

<div class="container mt-4">
    <div class="text-center mb-5">
        <h1 class="display-4">🍳 RecipeShare</h1>
        <p class="lead text-muted">Discover, share, and rate delicious recipes from around the world</p>
    </div>

    <h2 class="mb-4">Browse by Category</h2>
    <div class="row g-4">
        @foreach (var category in _categories)
        {
            <div class="col-md-4">
                <div class="card h-100 shadow-sm">
                    <div class="card-body text-center">
                        <span class="display-3">@category.Icon</span>
                        <h5 class="card-title mt-3">@category.Name</h5>
                        <p class="card-text text-muted">@category.Description</p>
                        <a href="/category/@category.Name" class="btn btn-outline-primary">Browse Recipes</a>
                    </div>
                </div>
            </div>
        }
    </div>

    <div class="text-center mt-5">
        <a href="/submit" class="btn btn-success btn-lg">📝 Submit Your Recipe</a>
    </div>
</div>

@code {
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private List<RecipeShare.Models.RecipeCategory> _categories = new();

    protected override void OnInitialized()
    {
        _categories = RecipeService.GetCategories();
    }
}

@page "/category/{CategoryName}"
@using RecipeShare.Services
@using RecipeShare.Models

<PageTitle>@CategoryName Recipes - RecipeShare</PageTitle>

<div class="container mt-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <h1>@CategoryName Recipes</h1>

    @if (_recipes.Count == 0)
    {
        <div class="alert alert-info">No recipes found in this category yet. <a href="/submit">Be the first to submit one!</a></div>
    }
    else
    {
        <div class="row g-4">
            @foreach (var recipe in _recipes)
            {
                <div class="col-md-6">
                    <div class="card h-100 shadow-sm">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <div class="mb-2">
                                @for (int i = 1; i <= 5; i++)
                                {
                                    <span class="text-warning">@(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")</span>
                                }
                                <small class="text-muted ms-2">@recipe.AverageRating / 5 (@recipe.RatingCount ratings)</small>
                            </div>
                            <a href="/recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private List<Recipe> _recipes = new();

    protected override void OnInitialized()
    {
        _recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/recipe/{RecipeId:int}"
@using RecipeShare.Services
@using RecipeShare.Models
@using RecipeShare.Components.Shared

<PageTitle>@(_recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>

<div class="container mt-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            @if (_recipe is not null)
            {
                <li class="breadcrumb-item"><a href="/category/@_recipe.Category">@_recipe.Category</a></li>
                <li class="breadcrumb-item active">@_recipe.Title</li>
            }
        </ol>
    </nav>

    @if (_recipe is null)
    {
        <div class="alert alert-warning">Recipe not found.</div>
    }
    else
    {
        <h1>@_recipe.Title</h1>
        <span class="badge bg-secondary mb-3">@_recipe.Category</span>

        <div class="row mt-4">
            <div class="col-md-4">
                <div class="card">
                    <div class="card-header"><strong>🧾 Ingredients</strong></div>
                    <ul class="list-group list-group-flush">
                        @foreach (var ingredient in _recipe.Ingredients.Split('\n'))
                        {
                            <li class="list-group-item">@ingredient</li>
                        }
                    </ul>
                </div>
            </div>
            <div class="col-md-8">
                <div class="card">
                    <div class="card-header"><strong>👨‍🍳 Instructions</strong></div>
                    <div class="card-body">
                        @foreach (var step in _recipe.Steps.Split('\n'))
                        {
                            <p>@step</p>
                        }
                    </div>
                </div>
            </div>
        </div>

        <div class="card mt-4">
            <div class="card-body">
                <h5>Rate this Recipe</h5>
                <StarRating RecipeId="_recipe.Id" @rendermode="InteractiveServer" />
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private Recipe? _recipe;

    protected override void OnInitialized()
    {
        _recipe = RecipeService.GetRecipeById(RecipeId);
    }
}

@using RecipeShare.Services

<div class="d-inline-block">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star-rating @(star <= _selectedRating ? "selected" : "")"
              @onclick="() => Rate(star)"
              role="button"
              title="@star star(s)">
            @(star <= _selectedRating ? "★" : "☆")
        </span>
    }
    @if (_submitted)
    {
        <span class="ms-2 text-success">✓ Thanks for rating!</span>
    }
</div>

<style>
    .star-rating {
        font-size: 1.5rem;
        cursor: pointer;
        color: #ffc107;
        transition: transform 0.1s;
    }
    .star-rating:hover {
        transform: scale(1.2);
    }
</style>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private int _selectedRating;
    private bool _submitted;

    private void Rate(int stars)
    {
        _selectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        _submitted = true;
    }
}

@using RecipeShare.Services
@using RecipeShare.Models

<EditForm Model="_submission" OnValidSubmit="HandleSubmit" FormName="recipeForm">
    <DataAnnotationsValidator />

    <div class="card">
        <div class="card-body">
            <div class="mb-3">
                <label for="title" class="form-label">Recipe Title</label>
                <InputText id="title" class="form-control" @bind-Value="_submission.Title" placeholder="e.g., Grandma's Apple Pie" />
            </div>

            <div class="mb-3">
                <label for="category" class="form-label">Category</label>
                <InputSelect id="category" class="form-select" @bind-Value="_submission.Category">
                    <option value="">-- Select a category --</option>
                    @foreach (var cat in _categories)
                    {
                        <option value="@cat.Name">@cat.Icon @cat.Name</option>
                    }
                </InputSelect>
            </div>

            <div class="mb-3">
                <label for="ingredients" class="form-label">Ingredients (one per line)</label>
                <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="_submission.Ingredients" placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs..." />
            </div>

            <div class="mb-3">
                <label for="steps" class="form-label">Steps (one per line)</label>
                <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="_submission.Steps" placeholder="1. Preheat oven to 350°F&#10;2. Mix dry ingredients..." />
            </div>

            <button type="submit" class="btn btn-success" disabled="@_submitted">
                @if (_submitted)
                {
                    <span>✓ Recipe Submitted!</span>
                }
                else
                {
                    <span>Submit Recipe</span>
                }
            </button>

            @if (_submitted)
            {
                <div class="alert alert-success mt-3">
                    Your recipe has been submitted successfully! <a href="/">Back to Home</a>
                </div>
            }
        </div>
    </div>
</EditForm>

@code {
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private RecipeSubmission _submission = new();
    private List<RecipeCategory> _categories = new();
    private bool _submitted;

    protected override void OnInitialized()
    {
        _categories = RecipeService.GetCategories();
    }

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(_submission.Title) || string.IsNullOrWhiteSpace(_submission.Category))
            return;

        RecipeService.SubmitRecipe(_submission);
        _submitted = true;
    }
}

